private string RenderDoctorPane(int categoryId)
{
    DataTable dt = GetDoctorData(categoryId);
    if (dt == null || dt.Rows.Count == 0)
        return "<div class=\"dept-empty\">Đang cập nhật dữ liệu bác sĩ.</div>";

    StringBuilder html = new StringBuilder();
    for (int i = 0; i < dt.Rows.Count; i++)
    {
        html.Append(RenderDoctorCard(dt.Rows[i], categoryId));
    }

    return html.ToString();
}

private string RenderDoctorCard(DataRow row, int categoryId)
{
    string hocVi = GetValue(row, "DoctorHocVi");
    string name = GetValue(row, "Title");
    string chuyenMon = GetValue(row, "DoctorChuyenMon");
    string chucVu = GetValue(row, "DoctorChucVu");
    string room = GetValue(row, "DoctorRoom");
    string time = GetValue(row, "DoctorTime");
    string brief = GetValue(row, "Brief");
    string link = GetDoctorUrl(row);
    string image = GetDoctorImage(row);
    string khoiLabel = GetDoctorKhoiLabel(categoryId);

    if (string.IsNullOrEmpty(chucVu))
        chucVu = brief;
    if (string.IsNullOrEmpty(chucVu))
        chucVu = chuyenMon;
    if (string.IsNullOrEmpty(room))
        room = GetValue(row, "CategoryName");

    StringBuilder html = new StringBuilder();
    html.AppendLine("<article class=\"kp-doctor-item\">");
    html.AppendLine("  <div class=\"item-single\">");
    html.AppendLine("    <div class=\"image\">");
    html.AppendLine("      <a href=\"" + HtmlAttribute(link) + "\" aria-label=\"" + HtmlAttribute(GetDetailLinkText() + " " + name) + "\">");
    if (!string.IsNullOrEmpty(image))
        html.AppendLine("        <img src=\"" + HtmlAttribute(image) + "\" alt=\"" + HtmlAttribute(name) + "\" class=\"lazy-fade\" loading=\"lazy\" decoding=\"async\" />");
    else
        html.AppendLine("        <span class=\"kp-doctor-placeholder\" aria-hidden=\"true\"><span class=\"fas fa-user-md\"></span></span>");
    html.AppendLine("      </a>");
    html.AppendLine("    </div>");
    html.AppendLine("    <div class=\"content\">");
    if (!string.IsNullOrEmpty(hocVi))
    {
        html.AppendLine("      <span class=\"location\">");
        html.AppendLine("        <i class=\"bx bx-briefcase\"></i>");
        html.AppendLine("        " + HtmlEncode(hocVi));
        html.AppendLine("      </span>");
    }
    html.AppendLine("      <h3>");
    html.AppendLine("        <a href=\"" + HtmlAttribute(link) + "\">" + HtmlEncode(name) + "</a>");
    html.AppendLine("      </h3>");
    if (!string.IsNullOrEmpty(chuyenMon))
    {
        html.AppendLine("      <div class=\"review\">");
        html.AppendLine("        <i class=\"bx bx-plus-medical\"></i>");
        html.AppendLine("        <span>" + HtmlEncode(StripHtml(chuyenMon, 120)) + "</span>");
        html.AppendLine("      </div>");
    }
    if (!string.IsNullOrEmpty(chucVu))
        html.AppendLine("      <p>" + HtmlEncode(StripHtml(chucVu, 140)) + "</p>");
    if (!string.IsNullOrEmpty(khoiLabel))
        html.AppendLine("      <div class=\"kp-doctor-khoi\">" + HtmlEncode(khoiLabel) + "</div>");
    html.AppendLine("      <a class=\"dept-detail-link\" href=\"" + HtmlAttribute(link) + "\">");
    html.AppendLine("        " + HtmlEncode(GetDetailLinkText()) + " <span class=\"arrow\" aria-hidden=\"true\">→</span>");
    html.AppendLine("      </a>");
    html.AppendLine("    </div>");
    html.AppendLine("    <div class=\"spacer\"></div>");
    html.AppendLine("  </div>");
    html.AppendLine("</article>");
    return html.ToString();
}

private string GetDoctorKhoiLabel(int categoryId)
{
    if (ResManager.CurrentLanguageID == 2)
    {
        if (categoryId == DoctorKhoiNoiCategoryId) return "INTERNAL MEDICINE EXPERTS";
        if (categoryId == DoctorKhoiNgoaiCategoryId) return "SURGICAL EXPERTS";
        if (categoryId == DoctorKhoiHoTroCategoryId) return "SUPPORT EXPERTS";
        return "";
    }

    if (categoryId == DoctorKhoiNoiCategoryId) return "CHUYÊN GIA KHỐI NỘI";
    if (categoryId == DoctorKhoiNgoaiCategoryId) return "CHUYÊN GIA KHỐI NGOẠI";
    if (categoryId == DoctorKhoiHoTroCategoryId) return "CHUYÊN GIA KHỐI HỖ TRỢ";
    return "";
}

