private string RenderDoctorInstructor(DataRow row, int index)
{
    string title = GetDoctorDisplayName(row);
    string position = GetValue(row, "DoctorChucVu");
    string room = GetValue(row, "DoctorRoom");
    string categoryName = GetValue(row, "CategoryName");
    string link = GetDoctorUrl(row);
    string image = GetDoctorImage(row);
    string entranceClass = (index % 4 < 2)
        ? "kp-instructors-two__single--from-left"
        : "kp-instructors-two__single--from-right";

    if (string.IsNullOrEmpty(room))
        room = categoryName;
    if (string.IsNullOrEmpty(position))
        position = GetValue(row, "DoctorChuyenMon");

    StringBuilder html = new StringBuilder();
    html.AppendLine("<article class=\"kp-instructors-two__single " + entranceClass + "\" style=\"--kp-instructor-delay: " + (((index % 8) + 1) * 70).ToString() + "ms;\" data-role=\"truong\">");
    html.AppendLine("  <div class=\"kp-instructors-two__img-box\">");
    html.AppendLine("    <a class=\"kp-instructors-two__img\" href=\"" + HtmlAttribute(link) + "\" aria-label=\"Xem hồ sơ " + HtmlAttribute(title) + "\">");
    html.AppendLine("      <span class=\"kp-instructors-two__photo-placeholder\" aria-hidden=\"true\">");
    html.AppendLine("        <span class=\"fas fa-user-md\"></span>");
    html.AppendLine("      </span>");
    if (!string.IsNullOrEmpty(image))
        html.AppendLine("      <img src=\"" + HtmlAttribute(image) + "\" alt=\"" + HtmlAttribute(title) + "\" loading=\"lazy\" decoding=\"async\" />");
    html.AppendLine("    </a>");
    html.AppendLine("  </div>");
    html.AppendLine("  <div class=\"kp-instructors-two__content\">");
    html.AppendLine("    <div class=\"kp-instructors-two__title-box\">");
    html.AppendLine("      <h3 class=\"kp-instructors-two__title\"><a href=\"" + HtmlAttribute(link) + "\">" + HtmlEncode(title) + "</a></h3>");
    if (!string.IsNullOrEmpty(position))
        html.AppendLine("      <p class=\"kp-instructors-two__sub-title\">" + HtmlEncode(StripHtml(position, 120)) + "</p>");
    if (!string.IsNullOrEmpty(room))
        html.AppendLine("      <p class=\"kp-instructors-two__department\">" + HtmlEncode(room) + "</p>");
    html.AppendLine("    </div>");
    html.AppendLine("  </div>");
    html.AppendLine("</article>");
    return html.ToString();
}

private string GetDoctorDisplayName(DataRow row)
{
    string title = GetValue(row, "Title");
    string degree = GetValue(row, "DoctorHocVi");

    if (string.IsNullOrEmpty(degree)) return title;
    if (!string.IsNullOrEmpty(title) && title.ToLower().StartsWith(degree.ToLower()))
        return title;

    return degree.Trim().TrimEnd('.') + ". " + title;
}

